package jp.schoolboard;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.time.*;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root,body;String tab="tasks";final int ink=0xffedf4ff,muted=0xff9aadc6;
 public void onCreate(Bundle b){super.onCreate(b);Reminder.schedule(this);show();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);if(getIntent().getBooleanExtra("add",false))edit(null);}
 public void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);if(i.getBooleanExtra("add",false))edit(null);}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(7),0,dp(7));return t;}
 void button(LinearLayout l,String label,Runnable action){TextView b=text(label,15,0xff7ee4d0);b.setPadding(dp(12),dp(14),dp(12),dp(14));b.setOnClickListener(v->action.run());l.addView(b);}
 void show(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(22),dp(28),dp(22),dp(12));root.setBackgroundColor(0xff0c1424);setContentView(root);root.addView(text("CAMPUS / DAILY",12,0xff7ee4d0));TextView title=text("School Board",30,ink);title.setTypeface(null,Typeface.BOLD);root.addView(title);root.addView(text(LocalDate.now()+"  ·  あなたの学校生活を、ひと目で。",12,muted));LinearLayout tabs=new LinearLayout(this);root.addView(tabs);button(tabs,"提出物",()->{tab="tasks";show();});button(tabs,"授業",()->{tab="lessons";show();});button(tabs,"カレンダー",()->{tab="events";show();});ScrollView sc=new ScrollView(this);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);sc.addView(body);if(tab.equals("tasks")){body.addView(text("提出物  /  未提出 "+Store.pending(this).size()+"件",20,ink));button(body,"＋ 提出物を登録",()->edit(null));JSONArray a=Store.tasks(this);if(a.length()==0)card("すっきり、準備完了。","提出物を追加して、期限を忘れずに。",null);List<JSONObject> sorted=new ArrayList<>();for(int j=0;j<a.length();j++)sorted.add(a.optJSONObject(j));sorted.sort(Comparator.comparing(o->o.optString("due")));for(JSONObject o:sorted)card((o.optBoolean("done")?"✓ ":"○ ")+o.optString("title"),o.optString("due")+"  /  "+o.optString("subject")+"\n"+o.optString("note"),()->taskActions(o));}else{body.addView(text(tab.equals("lessons")?"今日の授業":"これからの予定",20,ink));List<String> lines=Store.lines(this,tab);if(lines.isEmpty())card("予定はありません","設定から時間割・年間予定のJSONを読み込めます。",null);for(String line:lines)card(line,"",null);}LinearLayout footer=new LinearLayout(this);root.addView(footer);button(footer,"設定・データ更新",this::settings);button(footer,"ウィジェット",()->new AlertDialog.Builder(this).setMessage("ホーム画面の空いている場所を長押し → ウィジェット → School Board を追加してください。標準5×4で、サイズ変更にも対応します。表示件数は最大3件です。提出物をタップすると提出済みになります。追加・編集はアプリ画面で行います。").setPositiveButton("OK",null).show());}
 void card(String title,String detail,Runnable click){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),dp(12),dp(16),dp(12));GradientDrawable bg=new GradientDrawable();bg.setColor(0xff17263b);bg.setCornerRadius(dp(18));box.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(12);body.addView(box,lp);box.addView(text(title,19,ink));if(!detail.isEmpty())box.addView(text(detail,13,muted));if(click!=null)box.setOnClickListener(v->click.run());}
 EditText field(LinearLayout l,String hint,String value){EditText e=new EditText(this);e.setTextColor(ink);e.setHintTextColor(muted);e.setHint(hint);e.setText(value);l.addView(e);return e;}
 void taskActions(JSONObject o){new AlertDialog.Builder(this).setTitle(o.optString("title")).setItems(new String[]{o.optBoolean("done")?"未提出に戻す":"提出済みにする","編集","削除"},(d,n)->{if(n==0){Store.toggle(this,o.optString("id"));show();}if(n==1)edit(o);if(n==2)new AlertDialog.Builder(this).setMessage("この提出物を削除しますか？").setPositiveButton("削除",(x,y)->{JSONArray old=Store.tasks(this),a=new JSONArray();for(int j=0;j<old.length();j++)if(!old.optJSONObject(j).optString("id").equals(o.optString("id")))a.put(old.optJSONObject(j));Store.save(this,a);show();}).setNegativeButton("キャンセル",null).show();}).show();}
 void edit(JSONObject old){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(20),0,dp(20),0);EditText title=field(l,"提出物名",old==null?"":old.optString("title")),subject=field(l,"科目",old==null?"":old.optString("subject")),due=field(l,"期限 YYYY-MM-DD",old==null?LocalDate.now().plusDays(1).toString():old.optString("due")),note=field(l,"メモ",old==null?"":old.optString("note"));due.setFocusable(false);due.setOnClickListener(v->{LocalDate date=LocalDate.parse(due.getText().toString());new DatePickerDialog(this,(p,y,m,d)->due.setText(LocalDate.of(y,m+1,d).toString()),date.getYear(),date.getMonthValue()-1,date.getDayOfMonth()).show();});AlertDialog dialog=new AlertDialog.Builder(this).setTitle(old==null?"提出物を登録":"提出物を編集").setView(l).setPositiveButton("保存",null).setNegativeButton("キャンセル",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{if(title.getText().toString().trim().isEmpty()){title.setError("名前を入力してください");return;}LocalDate.parse(due.getText().toString());JSONObject o=new JSONObject();o.put("id",old==null?UUID.randomUUID().toString():old.getString("id"));o.put("title",title.getText().toString().trim());o.put("subject",subject.getText().toString());o.put("due",due.getText().toString());o.put("note",note.getText().toString());o.put("done",old!=null&&old.optBoolean("done"));JSONArray a=Store.tasks(this);boolean found=false;for(int j=0;j<a.length();j++)if(a.optJSONObject(j).optString("id").equals(o.getString("id"))){a.put(j,o);found=true;}if(!found)a.put(o);Store.save(this,a);dialog.dismiss();show();}catch(Exception e){Toast.makeText(this,"入力内容を確認してください",Toast.LENGTH_LONG).show();}}));dialog.show();}
 void settings(){new AlertDialog.Builder(this).setTitle("設定・データ更新").setItems(new String[]{"毎日の通知時刻（現在 "+String.format(java.util.Locale.JAPAN,"%02d:%02d",Store.p(this).getInt("hour",20),Store.p(this).getInt("minute",0))+"）","時間割・年間予定を読み込む","通知の許可を設定"},(d,n)->{if(n==0)new TimePickerDialog(this,(t,h,m)->{Store.p(this).edit().putInt("hour",h).putInt("minute",m).apply();Reminder.schedule(this);},Store.p(this).getInt("hour",20),Store.p(this).getInt("minute",0),true).show();if(n==1)startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),42);if(n==2)startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()));}).show();}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==42&&result==RESULT_OK&&data!=null){try(java.io.InputStream in=getContentResolver().openInputStream(data.getData())){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int count;while((count=in.read(b))!=-1){out.write(b,0,count);if(out.size()>1048576)throw new Exception("ファイルは1MB以下にしてください");}String raw=out.toString("UTF-8");new AlertDialog.Builder(this).setTitle("時間割・年間予定を更新").setMessage("既存の授業と年間予定をこのファイルで置き換えます。提出物は保持します。").setPositiveButton("更新",(d,n)->{try{Store.importData(this,raw);show();Toast.makeText(this,"更新しました",Toast.LENGTH_SHORT).show();}catch(Exception e){new AlertDialog.Builder(this).setMessage("更新できませんでした："+e.getMessage()).setPositiveButton("OK",null).show();}}).setNegativeButton("キャンセル",null).show();}catch(Exception e){Toast.makeText(this,"ファイルを読み込めませんでした",Toast.LENGTH_LONG).show();}}}
}
